Method.Source:
    public void processOperation()
    {
        LedgerJournalTable           ledgerJournalTable;
        LedgerJournalCheckPost       jourPost;

        while select ledgerJournalTable where
            ledgerJournalTable.METRPAInterface == true && ledgerJournalTable.Posted == false
            && ledgerJournalTable.WorkflowApprovalStatus == LedgerJournalWFApprovalStatus::Approved
        {
            jourPost = LedgerJournalCheckPost::newLedgerJournalTable(ledgerJournalTable, NoYes::Yes);
            jourPost.runOperation();

            info(strFmt("Workflow approved Journal %1 posted using METRPAGeneralJournalInterfacePostingService", ledgerJournalTable.JournalNum));
        }
    }
